using System.Collections.Generic;
using System.Linq;
using Microsoft.CodeAnalysis;
using Serein.Generator.Framework;

namespace ScriptLang.Generator;

internal static class PrototypeEmitter
{
    private const string Value = "global::ScriptLang.Runtime.Value";
    private const string Engine = "global::ScriptLang.ScriptEngine";
    internal static void Emit(PrototypeModel model, GenerationContext context)
    {
        var code = model.GenerateCode(context);
        context.AddSource(model.HintName, code);
    }

    private static string GenerateCode(this PrototypeModel model, GenerationContext context)
    {
        // File-scoped output also handles nested namespace declarations in the input.
        var body = new CodeBuilder<PrototypeModel>(context, model);
        body.AppendCode("// <auto-generated/>").AppendCode("#nullable enable");
        if (model.Namespace.Length != 0) body.AppendCode($"namespace {model.Namespace};");
        body.AppendCode($"partial class {model.ClassName} : global::ScriptLang.IPrototype");
        body.AppendCodeBlock(() =>
        {
            body.AppendCode($"private readonly global::System.Collections.Generic.Dictionary<string, global::System.Func<{Value}, {Engine}, {Value}>> _prototypeMethods = [];");
            body.AppendCode("bool _isLoad = false;").AppendCode("public bool IsLoad => _isLoad;");
            body.AppendCode($"public partial bool IsTarget({Value} value);");
            body.AppendCode($"{Value}? global::ScriptLang.IPrototype.GetMethod({Value} value, string methodName, {Engine} engine)")
                .AppendCode("    => _prototypeMethods.TryGetValue(methodName, out var func) ? func(value, engine) : null;");
            body.AppendCode("void global::ScriptLang.IPrototype.Init()");
            body.AppendCodeBlock(() =>
            {
                foreach (var method in model.Methods)
                {
                    context.CancellationToken.ThrowIfCancellationRequested();
                    body.AppendCode($"var {method.VariableName} = new global::System.Func<{Value}, {Engine}, {Value}>((v, env) =>");
                    body.AppendCodeBlock(() =>
                    {
                        if (method.Kind == PrototypeMemberKind.Property)
                        {
                            EmitReceiver(body, method);
                            body.AppendCode($"return {method.Name}({(model.PushThis ? "target" : "")});");
                        }
                        else
                        {
                            body.AppendCode($"return new global::ScriptLang.Runtime.FunctionValue({CSharpLiteral.RenderValue(method.ScriptName)}, {method.AsyncModifier}args =>");
                            body.AppendCodeBlock(() => EmitCall(body, method));
                            body.AppendCode(");");
                        }
                    });
                    body.AppendCode(");");
                    body.AppendCode($"_prototypeMethods[{CSharpLiteral.RenderValue(method.ScriptName)}] = {method.VariableName};");
                }
                body.AppendCode("_isLoad = true;");
            });
        });
        return body.ToCode();
    }

    private static void EmitReceiver(CodeBuilder<PrototypeModel> code, PrototypeMethod method)
    {
        if (!code.Cache.PushThis) return;
        var receiver = method.Parameters[0];
        // PrototypeManager resolves CLR receivers only after IsTarget accepts the wrapped value.
        // PrototypeManager 仅在 IsTarget 接受包装值后解析 CLR 接收对象。
        var expression = receiver.IsScriptValue ? "v" : "((global::ScriptLang.Runtime.ClrObjectValue)v).Value";
        code.AppendCode($"var target = ({receiver.TypeName}){expression}{(receiver.IsScriptValue ? "" : "!")};");
    }

    private static void EmitCall(CodeBuilder<PrototypeModel> code, PrototypeMethod method)
    {
        var start = code.Cache.PushThis ? 1 : 0;
        var arguments = method.Parameters.Skip(start).Where(parameter => !parameter.IsEngine).ToArray();
        var required = arguments.Count(parameter => !parameter.Optional);
        var message = arguments.Any(parameter => parameter.Optional)
            ? $"{method.ScriptName}() 至少需要 {required} 个参数" : $"{method.ScriptName}() 期望 {arguments.Length} 个参数";
        code.AppendCode($"if (args.Count < {required})");
        code.AppendCodeBlock(() => code.AppendCode($"throw new global::ScriptLang.Runtime.RuntimeException({CSharpLiteral.RenderValue(message)});"));
        for (var index = 0; index < arguments.Length; index++)
        {
            var argument = arguments[index];
            var optional = argument.Optional ? "?" : string.Empty;
            var missing = argument.Optional ? $"args.Count <= {index} ? default : " : string.Empty;
            code.AppendCode($"{argument.TypeName}{optional} arg{index} = {missing}args[{index}] is {argument.TypeName} _arg{index} ? _arg{index}")
                .AppendCode($"    : throw new global::ScriptLang.Runtime.RuntimeException({CSharpLiteral.RenderValue($"{method.ScriptName}() 第 {index + 1} 个参数期望 '{argument.DisplayName}' 类型值")});");
        }
        EmitReceiver(code, method);
        var names = new List<string>();
        if (code.Cache.PushThis) names.Add("target");
        var argumentIndex = 0;
        foreach (var parameter in method.Parameters.Skip(start)) names.Add(parameter.IsEngine ? "env" : "arg" + argumentIndex++);
        var call = $"{method.Name}({string.Join(", ", names)})";
        switch (method.Call)
        {
            case PrototypeCallKind.Void:
                code.AppendCode(call + ";");
                break;
            case PrototypeCallKind.AwaitVoid:
                code.AppendCode("await " + call + ";");
                break;
            case PrototypeCallKind.AwaitValue:
                code.AppendCode($"var result = await {call};").AppendCode("return result;");
                break;
            case PrototypeCallKind.Value:
                code.AppendCode($"var result = {call};").AppendCode("return result;");
                break;
        }
    }
}
